raw_response:
{
  "grammar_topic": "Preposition",
  "sentence_structure": "S + V + Prep Phrase (at 6:00 P.M.), + Prep + which + S + V + O.",
  "pattern": "time expression + comma + preposition + relative pronoun (which)",
  "vocabulary": [
    {
      "word": "lecture",
      "meaning": "bài giảng",
      "part_of_speech": "noun"
    },
    {
      "word": "attendee",
      "meaning": "người tham dự",
      "part_of_speech": "noun"
    },
    {
      "word": "after",
      "meaning": "sau khi",
      "part_of_speech": "preposition"
    }
  ],
  "explanation": "Câu hỏi kiểm tra việc lựa chọn giới từ phù hợp để kết hợp với mệnh đề quan hệ 'which' chỉ thời gian hoặc sự kiện. Cấu trúc ', after which...' được dùng để chỉ hành động xảy ra sau thời điểm hoặc sự kiện được nhắc đến trước đó (sau 6:00 chiều, những người tham dự có thể đặt câu hỏi). Do đó, 'after' là lựa chọn chính xác về mặt ngữ nghĩa và ngữ pháp.",
  "distractor_analysis": {
    "A": "across có nghĩa là băng qua hoặc ở bên kia, không phù hợp về ngữ nghĩa khi đi với mốc thời gian và mệnh đề chỉ hành động nối tiếp.",
    "B": "after là giới từ chính xác, chỉ thời gian diễn ra sự việc tiếp theo sau buổi thuyết giảng (sau 6:00 chiều).",
    "C": "inside có nghĩa là bên trong, chỉ vị trí không gian, không phù hợp để chỉ mối quan hệ thời gian hoặc sự kiện tiếp diễn.",
    "D": "among có nghĩa là ở giữa (từ ba đối tượng trở lên), không phù hợp về ngữ nghĩa trong ngữ cảnh chỉ thời điểm diễn ra sự việc."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Adjective Choice",
  "sentence_structure": "S (The _____ antique shop) + V (will close down) + Adv (next month).",
  "pattern": "The + [adjective] + [noun] + [verb phrase]",
  "vocabulary": [
    {
      "word": "antique shop",
      "meaning": "cửa hàng đồ cổ",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "close down",
      "meaning": "đóng cửa, ngừng hoạt động",
      "part_of_speech": "verb phrase"
    },
    {
      "word": "last",
      "meaning": "còn lại, cuối cùng",
      "part_of_speech": "adjective"
    }
  ],
  "explanation": "Câu này cần một tính từ đứng trước danh từ ghép 'antique shop' để bổ nghĩa cho nó. Tính từ 'last' (còn lại / cuối cùng) phù hợp về mặt ngữ nghĩa và ngữ pháp để tạo thành cụm danh từ 'the last antique shop' (cửa hàng đồ cổ cuối cùng ở Thung lũng Pepper).",
  "distractor_analysis": {
    "A": "Đáp án đúng. 'last' hoạt động như một tính từ bổ nghĩa cho cụm danh từ 'antique shop', diễn tả cửa hàng đồ cổ cuối cùng còn hoạt động.",
    "B": "Đáp án sai. 'lasts' là động từ chia ở ngôi thứ ba số ít thì hiện tại đơn, không thể đứng ở vị trí trước danh từ để làm định ngữ trong cấu trúc này.",
    "C": "Đáp án sai. 'lasted' là dạng quá khứ hoặc phân từ quá khứ của động từ 'last', không phù hợp về mặt ngữ pháp khi đặt trước danh từ chính trong câu này.",
    "D": "Đáp án sai. 'lasting' là phân từ hiện tại / tính từ mang nghĩa kéo dài, không tạo ra nghĩa hợp lý và tự nhiên trong ngữ cảnh chỉ cửa hàng cuối cùng còn lại."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "vocabulary / noun choice",
  "sentence_structure": "S (Merryville residents) + V (will receive) + O (an online status [blank]) + Prep (about the ongoing bridge construction project).",
  "pattern": "receive an online status update",
  "vocabulary": [
    {
      "word": "resident",
      "meaning": "cư dân",
      "part_of_speech": "noun"
    },
    {
      "word": "ongoing",
      "meaning": "đang diễn ra",
      "part_of_speech": "adjective"
    },
    {
      "word": "construction",
      "meaning": "sự xây dựng",
      "part_of_speech": "noun"
    },
    {
      "word": "update",
      "meaning": "bản cập nhật, thông tin mới nhất",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu hỏi kiểm tra khả năng sử dụng từ vựng (danh từ) phù hợp với ngữ cảnh câu và cụm từ cố định. Cụm từ 'status update' (bản cập nhật tình trạng/tiến độ) là một collocation rất phổ biến khi nói về các dự án đang thi công như 'bridge construction project'. Do đó, 'update' là lựa chọn chính xác nhất.",
  "distractor_analysis": {
    "A": "Đáp án chính xác. 'Update' kết hợp với 'status' tạo thành cụm 'status update' (bản cập nhật trạng thái), hoàn toàn phù hợp với ngữ cảnh thông báo về tiến độ dự án cầu.",
    "B": "Mặc dù 'change' là danh từ hợp nghĩa chung, nhưng cụm 'status change' ít tự nhiên hơn 'status update' trong ngữ cảnh nhận thông tin về một dự án đang thi công.",
    "C": "Danh từ 'payment' (thanh toán, khoản thanh toán) không phù hợp về mặt ngữ nghĩa với việc nhận thông tin trực tuyến về một dự án xây dựng cầu.",
    "D": "Danh từ 'request' (yêu cầu) không hợp nghĩa trong bối cảnh cư dân nhận được thông tin về tiến độ xây dựng."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Pronouns",
  "sentence_structure": "Prep (As a result of) + Possessive Determiner (her) + Noun (years) + Participle Phrase (leading media organizations), + S (Ms. Ayo) + V (was selected) + Prep Phrase (for the Dowel Journalism Prize).",
  "pattern": "As a result of + [possessive determiner] + [noun]",
  "vocabulary": [
    {
      "word": "result",
      "meaning": "kết quả",
      "part_of_speech": "noun"
    },
    {
      "word": "leading",
      "meaning": "dẫn dắt, lãnh đạo",
      "part_of_speech": "adjective"
    },
    {
      "word": "media",
      "meaning": "truyền thông",
      "part_of_speech": "noun"
    },
    {
      "word": "selected",
      "meaning": "được lựa chọn",
      "part_of_speech": "verb"
    }
  ],
  "explanation": "Chỗ trống đứng trước cụm danh từ \"many years\", vì vậy vị trí này cần một tính từ sở hữu để bổ nghĩa cho danh từ theo sau. Đại từ sở hữu cách \"her\" (của cô ấy) là lựa chọn chính xác để kết hợp với cụm từ \"many years leading media organizations\".",
  "distractor_analysis": {
    "A": "Đáp án này sai vì \"she\" là đại từ nhân xưng chủ ngữ, không thể đứng trước cụm danh từ để chỉ sở hữu.",
    "B": "Đáp án này chính xác vì \"her\" đóng vai trò là tính từ sở hữu đứng trước danh từ \"years\".",
    "C": "Đáp án này sai vì \"hers\" là đại từ sở hữu độc lập, không đi kèm trực tiếp với danh từ phía sau.",
    "D": "Đáp án này sai vì \"herself\" là đại từ phản thân, không phù hợp về mặt ngữ pháp và ngữ nghĩa trong vị trí này."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Noun Selection / Vocabulary in Context",
  "sentence_structure": "To stop the [Noun] of computer viruses, do not open suspicious e-mails.",
  "pattern": "stop + the + [noun] + of + [noun]",
  "vocabulary": [
    {
      "word": "spread",
      "meaning": "sự lây lan",
      "part_of_speech": "noun"
    },
    {
      "word": "computer virus",
      "meaning": "vi-rút máy tính",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "suspicious",
      "meaning": "đáng ngờ",
      "part_of_speech": "adjective"
    },
    {
      "word": "e-mail",
      "meaning": "thư điện tử",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này kiểm tra khả năng chọn từ vựng phù hợp về mặt ngữ nghĩa để điền vào vị trí danh từ sau mạo từ 'the' và trước giới từ 'of'. Cụm từ 'the spread of computer viruses' có nghĩa là 'sự lây lan của vi-rút máy tính', hoàn toàn phù hợp với ngữ cảnh của câu khuyên không nên mở các email đáng ngờ để ngăn chặn vi-rút.",
  "distractor_analysis": {
    "A": "Đáp án 'break' không tạo thành một cụm từ có nghĩa hợp lý với ngữ cảnh ngăn chặn vi-rút máy tính. 'Break' ở đây không phù hợp với cấu trúc 'the break of'.",
    "B": "Đáp án 'spread' là danh từ chính xác nhất, tạo thành cụm từ 'the spread of computer viruses' (sự lây lan của vi-rút máy tính), khớp hoàn hảo với hành động ngăn chặn qua việc không mở email đáng ngờ.",
    "C": "Đáp án 'balance' (sự cân bằng) không phù hợp về mặt ngữ nghĩa trong ngữ cảnh ngăn chặn vi-rút máy tính.",
    "D": "Đáp án 'surface' (bề mặt) không tạo ra ý nghĩa hợp lý khi kết hợp với 'of computer viruses' trong ngữ cảnh này."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Noun Collocation / Compound Noun",
  "sentence_structure": "S (Tarateer Pharmaceuticals) + V (is varying) + O (its product line) + Prep Phrase (to include over-the-counter medications).",
  "pattern": "product + line (product line)",
  "vocabulary": [
    {
      "word": "pharmaceuticals",
      "meaning": "dược phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "varying",
      "meaning": "đang thay đổi, đa dạng hóa",
      "part_of_speech": "verb"
    },
    {
      "word": "product",
      "meaning": "sản phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "medications",
      "meaning": "thuốc, các dược phẩm",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này kiểm tra kiến thức về cụm danh từ (noun collocation). Cụm từ cố định 'product line' có nghĩa là 'dòng sản phẩm'. Tính từ sở hữu 'its' đứng trước cần một danh từ hoặc cụm danh từ làm tân ngữ cho động từ 'varying'. 'line' là danh từ chính xác tạo nên cụm từ có nghĩa trong ngữ cảnh này.",
  "distractor_analysis": {
    "A": "Sai cấu trúc ngữ pháp vì cụm từ kết hợp nguyên mẫu 'to line' không phù hợp với chức năng làm danh từ chỉ định vị trí tân ngữ sau tính từ sở hữu 'its'.",
    "B": "Dạng V-ing 'lining' không tạo thành cụm danh từ chuẩn xác với từ 'product' trong ngữ cảnh kinh doanh này.",
    "C": "Dạng quá khứ phân từ/phân từ II 'lined' không phù hợp về mặt ngữ nghĩa và cấu trúc cú pháp ở vị trí tân ngữ sau tính từ sở hữu.",
    "D": "Đáp án chính xác. 'line' kết hợp với 'product' tạo thành cụm danh từ quen thuộc 'product line' (dòng sản phẩm), hoàn toàn phù hợp với ngữ nghĩa của câu."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Verb Tense and Subject-Verb Agreement",
  "sentence_structure": "S (Dynart, Inc.) + Adv (continuously) + V (_____ new ways) + O (to reduce its use of plastics).",
  "pattern": "Subject + Adverb + Main Verb (Present Simple) + Object",
  "vocabulary": [
    {
      "word": "continuously",
      "meaning": " liên tục, liên tiếp",
      "part_of_speech": "adverb"
    },
    {
      "word": "reduce",
      "meaning": "giảm bớt, làm giảm",
      "part_of_speech": "verb"
    },
    {
      "word": "plastics",
      "meaning": "chất nhựa, đồ nhựa",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này thiếu một động từ chính để tạo thành câu hoàn chỉnh vì chủ ngữ là danh từ số ít 'Dynart, Inc.' và trạng từ chỉ tần suất 'continuously' đứng trước vị trí trống. Thì hiện tại đơn được dùng để diễn tả một hành động thường xuyên hoặc một chính sách liên tục của công ty. Do đó, 'seeks' (động từ số ít ở thì hiện tại đơn) là lựa chọn chính xác.",
  "distractor_analysis": {
    "A": "Đáp án đúng. 'seeks' là động từ chia ở thì hiện tại đơn, phù hợp với chủ ngữ số ít 'Dynart, Inc.'.",
    "B": "'seeker' là danh từ chỉ người (người tìm kiếm), không thể đứng làm động từ chính trong câu.",
    "C": "'to seek' là động từ nguyên mẫu có 'to', không thể đóng vai trò là động từ chính của câu thiếu vị ngữ.",
    "D": "'seeking' là danh từ/động từ dạng V-ing, không thể đứng độc lập làm động từ chính của câu ở thì hiện tại đơn mà không có trợ động từ."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Word Form",
  "sentence_structure": "S (The cash registers) + Adv (automatically) + V (blank) + O (the remaining inventory of books available).",
  "pattern": "Subject + Adverb + Verb + Object",
  "vocabulary": [
    {
      "word": "cash register",
      "meaning": "máy tính tiền",
      "part_of_speech": "noun"
    },
    {
      "word": "automatically",
      "meaning": "một cách tự động",
      "part_of_speech": "adverb"
    },
    {
      "word": "inventory",
      "meaning": "hàng tồn kho",
      "part_of_speech": "noun"
    },
    {
      "word": "calculate",
      "meaning": "tính toán",
      "part_of_speech": "verb"
    }
  ],
  "explanation": "Câu này thiếu động từ chính cho chủ ngữ số nhiều 'The cash registers'. Phía sau trạng từ 'automatically' cần một động từ nguyên mẫu ở thì hiện tại đơn để hoàn thành cấu trúc S + Adv + V + O. Do đó, 'calculate' (động từ) là đáp án chính xác.",
  "distractor_analysis": {
    "A": "calculate là động từ nguyên mẫu, phù hợp làm vị ngữ chính cho chủ ngữ số nhiều 'The cash registers' đi sau trạng từ 'automatically'.",
    "B": "calculator là danh từ chỉ người hoặc máy tính, không thể đứng sau trạng từ 'automatically' để làm vị ngữ trong cấu trúc này.",
    "C": "calculating là dạng phân từ hiện tại hoặc danh động từ, không thể đóng vai trò là động từ chính của câu khi thiếu trợ động từ.",
    "D": "calculation là danh từ, không phù hợp đứng ở vị trí cần động từ chính sau chủ ngữ và trạng từ."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Adverb Choice",
  "sentence_structure": "S + V + O + [can + Adv + V]",
  "pattern": "can + precisely + locate",
  "vocabulary": [
    {
      "word": "mapping",
      "meaning": "lập bản đồ",
      "part_of_speech": "noun"
    },
    {
      "word": "software",
      "meaning": "phần mềm",
      "part_of_speech": "noun"
    },
    {
      "word": "locate",
      "meaning": "xác định vị trí",
      "part_of_speech": "verb"
    },
    {
      "word": "precisely",
      "meaning": "chính xác",
      "part_of_speech": "adverb"
    }
  ],
  "explanation": "Câu hỏi yêu cầu chọn một trạng từ phù hợp để bổ nghĩa cho động từ \"locate\" (xác định vị trí) trong ngữ cảnh thiết kế phần mềm lập bản đồ ngầm. Từ \"precisely\" (một cách chính xác) là lựa chọn hợp lý nhất về mặt ngữ nghĩa, vì phần mềm bản đồ cần xác định vị trí khoáng sản một cách chính xác.",
  "distractor_analysis": {
    "A": "Sai về ngữ nghĩa. \"Infinitely\" có nghĩa là \"vô hạn\", không phù hợp để mô tả hành động xác định vị trí khoáng sản của phần mềm.",
    "B": "Sai về ngữ nghĩa. \"Sincerely\" có nghĩa là \"một cách chân thành\", thường dùng trong thư tín hoặc thái độ của con người, không phù hợp với ngữ cảnh kỹ thuật.",
    "C": "Đáp án chính xác. \"Precisely\" (chính xác) bổ nghĩa hoàn hảo cho động từ \"locate\", phản ánh đúng chức năng của phần mềm lập bản đồ khoáng sản.",
    "D": "Không phù hợp bằng C. \"Greatly\" có nghĩa là \"đáng kể, rất\", thường dùng để bổ nghĩa cho mức độ của tính từ hoặc động từ chỉ sự thay đổi/cảm xúc, không tự nhiên khi đi với \"locate\" trong ngữ cảnh này."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Word Form (Adverb vs. Adjective)",
  "sentence_structure": "Prep (According to CEO Mayu Yamada), S (it) V (would not be) [blank] Adj (responsible) Inf (to expand the warehouse) Adv (at this time).",
  "pattern": "Be + [Adverb] + Adjective",
  "vocabulary": [
    {
      "word": "responsible",
      "meaning": "có trách nhiệm",
      "part_of_speech": "adjective"
    },
    {
      "word": "expand",
      "meaning": "mở rộng",
      "part_of_speech": "verb"
    },
    {
      "word": "warehouse",
      "meaning": "kho hàng",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Chỗ trống cần một trạng từ để bổ nghĩa cho tính từ \"responsible\" đứng ngay sau nó (\"financially responsible\" có nghĩa là có trách nhiệm về mặt tài chính). Do đó, trạng từ \"financially\" là lựa chọn chính xác.",
  "distractor_analysis": {
    "A": "finance là danh từ hoặc động từ, không phù hợp để đứng trước và bổ nghĩa cho tính từ \"responsible\".",
    "B": "financials là danh từ số nhiều (các báo cáo tài chính), không thể đứng ở vị trí này để bổ nghĩa cho tính từ.",
    "C": "financially là trạng từ, hoàn toàn chính xác để bổ nghĩa cho tính từ \"responsible\" theo cấu trúc Trạng từ + Tính từ.",
